import bpy,json
from pathlib import Path
from mathutils import Vector
root=Path(bpy.data.filepath).parent.parent
out=root/'captures/surface_pass_20261113'
out.mkdir(exist_ok=True)
collections=[]
objects=[]
materials=set()
for c in bpy.data.collections:
 if any(k in c.name for k in ['Shipyard_COMBINED','Boat_Workshop','Boat_Export']):
  collections.append({'name':c.name,'count':len(c.objects),'hidden':[c.hide_viewport,c.hide_render]})
  for o in c.objects:
   if o.type!='MESH':continue
   ms=[m.name for m in o.data.materials if m];materials.update(ms)
   bb=[o.matrix_world@Vector(v) for v in o.bound_box]
   objects.append({'collection':c.name,'name':o.name,'materials':ms,'verts':len(o.data.vertices),'polygons':len(o.data.polygons),'location':list(o.location),'scale':list(o.scale),'dimensions':list(o.dimensions),'bounds_min':[min(v[i] for v in bb) for i in range(3)],'bounds_max':[max(v[i] for v in bb) for i in range(3)],'modifiers':[{'name':m.name,'type':m.type,**({'width':m.width,'segments':m.segments} if m.type=='BEVEL' else {})} for m in o.modifiers]})
mats=[]
for name in sorted(materials):
 m=bpy.data.materials[name];nodes=[]
 if m.use_nodes:
  for n in m.node_tree.nodes:
   d={'name':n.name,'type':n.type}
   if n.type=='TEX_IMAGE' and n.image:d.update(image=n.image.name,path=bpy.path.abspath(n.image.filepath),size=list(n.image.size),colorspace=n.image.colorspace_settings.name)
   if n.type in ['BSDF_PRINCIPLED','NORMAL_MAP','BUMP']:
    vals={}
