     if s.name in ['Base Color','Metallic','Roughness','IOR','Strength','Distance','Coat Weight','Specular IOR Level']:
      v=s.default_value;vals[s.name]={'value':list(v) if hasattr(v,'__len__') and not isinstance(v,str) else v,'linked':s.is_linked}
    d['values']=vals
   nodes.append(d)
 mats.append({'name':name,'users':m.users,'nodes':nodes,'links':[[l.from_node.name,l.from_socket.name,l.to_node.name,l.to_socket.name] for l in m.node_tree.links] if m.use_nodes else []})
d={'file':bpy.data.filepath,'collections':collections,'objects':objects,'materials':mats,'all_collection_names':[(c.name,len(c.objects)) for c in bpy.data.collections]}
(out/'state_before.json').write_text(json.dumps(d,indent=2),encoding='utf8')
